/**
 * R21.9 — RbPanZoom: content-type-agnostic pan/zoom controller (DRY, AC-f1/f2).
 *
 * CSS transform translate(tx,ty) scale(s) with transform-origin:0 0 on the content (AC-b1).
 * scale clamped [1,8] (AC-b2); zoom-about-point keeps the cursor/pinch-midpoint stationary
 * tx'=px-f*(px-tx) (AC-b3); tx/ty clamped so content can't leave view, recenters at s=1 (AC-b4).
 * Wheel zoom about cursor, passive:false (AC-c1); mouse drag pans only when s>1 (AC-c2);
 * 1-finger pan when s>1 (no page-scroll hijack at s=1, AC-d1); 2-finger pinch about midpoint
 * + pan by midpoint delta (AC-d2); double-tap toggles reset<->2x at tap point (AC-d3).
 * Listeners on the VIEWPORT only (AC-e3); e.target hit-test never elementFromPoint (AC-e2);
 * destroy() removes all listeners (AC-e4); iframe pointer-events:none during gesture —
 * on BOTH touch (touchstart) and desktop drag (mousedown), restored on idle (AC-e5).
 */
export class RbPanZoom {
  private scale = 1;
  private tx = 0;
  private ty = 0;
  private readonly MIN = 0.25; // R33.7.1 (INV-Z1): allow zoom-OUT below 1 → grows the working canvas (was 1 = no zoom-out)
  private readonly GROW_MIN = 0.02; // R33.7.1 BUG-1 (bc21ca747): grow mode has a (near-)no floor → REPEATED zoom-out keeps growing the canvas (endless-in-practice), bounded only by the host's MAX-CANVAS-PX safety cap. (A MIN=0.25 hard floor capped repeated zoom-out — the device regression.)
  onZoomEnd?: (scale: number) => void; // R33.7.1: fired (debounced) after a USER zoom settles → host persists per-diagram
  private zoomEndTimer = 0;
  growMode = false; // R33.7.1 canvas-grow: OPT-IN (diagram only). true → scale<1 GROWS the SVG canvas via onCanvasGrow (native scroll) instead of CSS-shrinking. rb-webitem/rb-preview leave it false = CSS-scale UNCHANGED.
  onCanvasGrow?: (scale: number) => void; // host grows/restores the SVG canvas dims+viewBox for the current scale (grow at <1, reset at >=1)
  private readonly MAX = 8;
  private dragging = false;
  private enabled = true; // R33.5 item3: PAN gated by selection — disabled while a diagram box is selected
  private lastX = 0;
  private lastY = 0;
  private pinchDist = 0;
  private pinchMidX = 0;
  private pinchMidY = 0;
  private lastTapTime = 0;
  private lastTapX = 0;
  private lastTapY = 0;
  private boundoff: Array<() => void> = [];

  constructor(private viewport: HTMLElement, private content: HTMLElement) {
    this.attach();
    this.apply();
  }

  private on<K extends keyof HTMLElementEventMap>(t: K, fn: (e: HTMLElementEventMap[K]) => void, opts?: AddEventListenerOptions): void {
    this.viewport.addEventListener(t, fn as EventListener, opts);
    this.boundoff.push(() => this.viewport.removeEventListener(t, fn as EventListener, opts));
  }

  // [impl:uuid:0564d93b-b492-4314-9dad-a53f7ea131af] R22.2 RbPanZoom.attach (mouse handlers)
  // [impl:uuid:58a7c149-8ea3-413d-9c77-e35aee70f2fd] RbPanZoom.attach (R40.29 pointer-unified background pan at all scales — DISTINCT from 0564d93b/R22.2, R30.11 no-re-credit; host method is `attach`, req-minted as attachMouse)
  private attach(): void {
    this.on('wheel', (e) => { // AC-c1
      e.preventDefault();
      const factor = e.deltaY < 0 ? 1.15 : 1 / 1.15;
      this.zoomAbout(e.offsetX, e.offsetY, factor);
    }, { passive: false });

    // v0.6.99: suppress the browser's native image/link drag so a mouse pan doesn't spawn a drag-ghost overlay.
    this.on('dragstart', (e) => e.preventDefault());
    // R40.29 — UNIFY the mouse/pen background-drag pan onto POINTER events (ONE path; the old separate mouse handlers
    // are GONE — a divergent 2nd path is how the s<=1 gap was born). Pans at ALL scales: the old `scale<=1` early-return
    // is removed, so the mouse now pans even when zoomed-out/at-fit — matching what TOUCH already did via native scroll.
    // growMode + scale<1 (a grown, scrollable canvas) → pan via native scroll (parity with touch); otherwise via the CSS
    // tx/ty transform (s>1; at s<=1 non-grow the clamp recenters = harmless no-op). A ~4px threshold keeps a click from
    // being a pan (so node-selection still fires); the `enabled` gate (pan OFF while a box is selected) keeps a
    // selected-box drag moving the box, not the canvas — the same background-vs-node guardrails the old path relied on,
    // now extended to every scale. ★ TOUCH is intentionally NOT moved onto pointer — the touch handlers below (pinch /
    // 1-finger / double-tap) are battle-tested and touch already pans at every scale, so leaving them untouched = ZERO
    // touch regression by construction; pointerType==='touch' is ignored here so there is no double-handling.
    let panDownX = 0, panDownY = 0, panning = false, panArmed = false, panPid = -1;
    this.on('pointerdown', (e) => {
      if (e.pointerType === 'touch') return;             // touch → its own handlers (no double-handling)
      if (!this.enabled) return;                          // R33.5: pan OFF while a box is selected (node-drag owns it)
      panArmed = true; panning = false; panPid = e.pointerId;
      panDownX = e.clientX; panDownY = e.clientY; this.lastX = e.clientX; this.lastY = e.clientY;
    });
    this.on('pointermove', (e) => {
      if (!panArmed || e.pointerId !== panPid) return;
      const dx = e.clientX - this.lastX, dy = e.clientY - this.lastY;
      if (!panning) { // threshold: a click (< ~4px) is a selection, NOT a pan
        if (Math.abs(e.clientX - panDownX) < 4 && Math.abs(e.clientY - panDownY) < 4) return;
        panning = true; this.dragging = true; this.viewport.style.cursor = 'grabbing'; this.gesturing(); // AC-e5 iframe capture off
      }
      if (this.growMode && this.scale < 1) { this.viewport.scrollLeft -= dx; this.viewport.scrollTop -= dy; } // pan the grown canvas (touch-parity)
      else { this.tx += dx; this.ty += dy; this.clamp(); this.apply(); }                                     // CSS-transform pan
      this.lastX = e.clientX; this.lastY = e.clientY;
    });
    const endPan = (e: PointerEvent) => {
      if (panPid !== -1 && e.pointerId !== panPid) return;
      panArmed = false; panning = false; this.dragging = false; panPid = -1;
      this.viewport.style.cursor = this.scale > 1 ? 'grab' : 'auto'; this.idle();
    };
    this.on('pointerup', endPan);
    this.on('pointercancel', endPan);
    this.on('pointerleave', endPan);
    this.on('dblclick', (e) => this.doubleTapToggle(e.clientX, e.clientY)); // R22.2 mouse-parity: dblclick toggles reset<->2x (touch already has double-tap)

    this.on('touchstart', (e) => {
      this.gesturing();
      if (e.touches.length === 2) {
        this.pinchDist = this.dist(e.touches[0], e.touches[1]);
        const mid = this.mid(e.touches[0], e.touches[1]);
        this.pinchMidX = mid.x; this.pinchMidY = mid.y;
      } else if (e.touches.length === 1) {
        const t = e.touches[0]; this.lastX = t.clientX; this.lastY = t.clientY;
        // double-tap detector (AC-e1): single-finger start
        const now = Date.now();
        if (now - this.lastTapTime < 300 && Math.abs(t.clientX - this.lastTapX) < 30 && Math.abs(t.clientY - this.lastTapY) < 30) {
          this.pendingDoubleTap = true;
        }
        this.lastTapX = t.clientX; this.lastTapY = t.clientY;
      }
    }, { passive: false });

    this.on('touchmove', (e) => {
      if (e.touches.length === 2) {
        e.preventDefault();
        const d = this.dist(e.touches[0], e.touches[1]);
        const mid = this.mid(e.touches[0], e.touches[1]);
        const rect = this.viewport.getBoundingClientRect();
        const px = mid.x - rect.left, py = mid.y - rect.top;
        if (this.pinchDist > 0) this.zoomAbout(px, py, d / this.pinchDist);
        // pan by midpoint delta (AC-d2)
        this.tx += (mid.x - this.pinchMidX); this.ty += (mid.y - this.pinchMidY);
        this.pinchDist = d; this.pinchMidX = mid.x; this.pinchMidY = mid.y;
        this.clamp(); this.apply();
      } else if (e.touches.length === 1 && this.scale > 1 && this.enabled) {
        e.preventDefault(); // AC-d1: only hijack scroll when zoomed
        const t = e.touches[0];
        this.tx += t.clientX - this.lastX; this.ty += t.clientY - this.lastY;
        this.lastX = t.clientX; this.lastY = t.clientY;
        this.clamp(); this.apply();
      }
    }, { passive: false });

    this.on('touchend', (e) => {
      if (e.touches.length === 0) { // AC-e1: gesture fully ended
        if (this.pendingDoubleTap) { this.pendingDoubleTap = false; this.doubleTapToggle(this.lastTapX, this.lastTapY); }
        this.lastTapTime = Date.now();
        this.pinchDist = 0;
        this.idle();
      }
    });
  }

  private pendingDoubleTap = false;

  // [impl:uuid:7831f755-af9a-424d-9505-8bdbb92d6f84] R22.2 RbPanZoom.doubleTapToggle — mouse dblclick + touch double-tap parity
  private doubleTapToggle(clientX: number, clientY: number): void { // AC-d3
    const rect = this.viewport.getBoundingClientRect();
    if (this.scale > 1) { this.reset(); }
    else { this.scale = 1; this.tx = 0; this.ty = 0; this.zoomAbout(clientX - rect.left, clientY - rect.top, 2); }
  }

  /** AC-b3: zoom about (px,py) in viewport coords, keeping that point stationary. */
  zoomAbout(px: number, py: number, factor: number): void {
    const floor = this.growMode ? this.GROW_MIN : this.MIN; // R33.7.1 BUG-1: grow mode has (near-)no floor → endless zoom-out
    const oldScale = this.scale;
    const ns = Math.max(floor, Math.min(this.MAX, oldScale * factor));
    const f = ns / oldScale;
    this.tx = px - f * (px - this.tx);
    this.ty = py - f * (py - this.ty);
    this.scale = ns;
    this.clamp(); this.apply(); // apply() grows the canvas via onCanvasGrow when growMode && scale<1
    if (this.growMode && ns < 1) {
      // R33.7.1 BUG-1 (bc21ca747): grow-mode zoom-about via NATIVE SCROLL — the canvas just grew by oldScale/ns, so
      // scroll the viewport to keep the point under (px,py) stationary (the CSS about-point math is identity in grow mode).
      const ratio = oldScale / ns;
      this.viewport.scrollLeft = Math.max(0, (this.viewport.scrollLeft + px) * ratio - px);
      this.viewport.scrollTop = Math.max(0, (this.viewport.scrollTop + py) * ratio - py);
    }
    this.scheduleZoomEnd(); // R33.7.1: user zoom → persist after it settles
  }

  // R33.7.1: debounce a user zoom so the host persists ONE value after the gesture settles (not every wheel tick).
  private scheduleZoomEnd(): void {
    if (!this.onZoomEnd) return;
    if (this.zoomEndTimer) clearTimeout(this.zoomEndTimer);
    this.zoomEndTimer = (setTimeout(() => this.onZoomEnd?.(this.scale), 450) as unknown) as number;
  }

  private clamp(): void { // AC-b4
    const vw = this.viewport.clientWidth, vh = this.viewport.clientHeight;
    const minTx = Math.min(0, vw - vw * this.scale);
    const minTy = Math.min(0, vh - vh * this.scale);
    this.tx = Math.min(0, Math.max(minTx, this.tx));
    this.ty = Math.min(0, Math.max(minTy, this.ty));
    // R33.7.1 (INV-Z1): at scale ≤ 1 CENTER the content — at 1 that's (0,0) = whole-diagram fit (100%); below 1 it
    // centers the shrunken diagram so the grown empty canvas surrounds it (working room), instead of pinning top-left.
    if (this.scale <= 1) { this.tx = (vw - vw * this.scale) / 2; this.ty = (vh - vh * this.scale) / 2; }
  }

  private apply(): void { // AC-b1
    this.content.style.transformOrigin = '0 0';
    if (this.growMode && this.scale < 1) {
      // R33.7.1 canvas-grow: NO CSS scale (identity) — the host (onCanvasGrow) grows the SVG canvas dims + viewBox
      // (base/scale, 1:1) so boxes keep visual size + placeable room appears; native surface scroll pans the canvas.
      this.content.style.transform = 'translate(0px, 0px) scale(1)';
      this.onCanvasGrow?.(this.scale);
    } else {
      this.content.style.transform = `translate(${this.tx}px, ${this.ty}px) scale(${this.scale})`;
      if (this.growMode) this.onCanvasGrow?.(1); // >=1 magnify → reset the canvas to base (host restores tight viewBox/overflow:hidden)
    }
    this.viewport.style.cursor = this.scale > 1 ? 'grab' : 'auto';
  }

  /** AC-e6 / reset to identity. */
  reset(): void { this.scale = 1; this.tx = 0; this.ty = 0; this.apply(); }

  // [impl:uuid:301b71d4-8c50-4e3f-80fa-6e30ae035f2c] RbPanZoom.setScale (Method c3fa13b7) — R33.7.1: set the zoom
  // level directly (restore a persisted per-diagram model.zoom), reusing the SAME clamp+apply as gestures (INV-Z3 no
  // fork). Clamped to [MIN,MAX]; the extended clamp centers content when <1 (INV-Z1: 1=100%=whole-diagram, <1=grown
  // canvas). Does NOT fire onZoomEnd — this is the restore path, not a user change (no persist-on-restore loop).
  setScale(s: number): void { const floor = this.growMode ? this.GROW_MIN : this.MIN; this.scale = Math.max(floor, Math.min(this.MAX, s)); this.clamp(); this.apply(); }
  get currentScale(): number { return this.scale; }

  // [impl:uuid:7dd375ac-28f1-4768-9063-bdf6fa430ce5] RbPanZoom.panBy (Method 1a2fbff9) — R33.6.2 INV-D2: programmatic
  // pan by (dx,dy) viewport px, reusing the SAME clamp+apply as gesture pans (no new geometry, INV-D3 no-fork). The
  // diagram edge-autoscroll rAF loop calls this while a box-drag hovers just outside the surface boundary → the
  // canvas scrolls so a box can be dragged toward off-screen space; clamp keeps content from leaving the view.
  panBy(dx: number, dy: number): void { this.tx += dx; this.ty += dy; this.clamp(); this.apply(); }

  // [impl:uuid:44f3ddd3-c580-4fe7-8e3c-489cf05c4e42] RbPanZoom.setEnabled (Method 4dab0081) — R33.5 item3: enable/
  // disable PAN (not zoom). The diagram disables pan while a box is SELECTED so a selected-box drag MOVES the box
  // (no canvas pan); re-enabled when the selection clears. Also cancels any in-progress drag.
  setEnabled(on: boolean): void { this.enabled = on; if (!on) this.dragging = false; }
  get isEnabled(): boolean { return this.enabled; }

  private gesturing(): void { // AC-e5: disable iframe pointer capture mid-gesture
    this.content.querySelectorAll('iframe').forEach(f => (f as HTMLElement).style.pointerEvents = 'none');
  }
  private idle(): void {
    this.content.querySelectorAll('iframe').forEach(f => (f as HTMLElement).style.pointerEvents = '');
  }

  private dist(a: Touch, b: Touch): number { return Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY); }
  private mid(a: Touch, b: Touch): { x: number; y: number } { return { x: (a.clientX + b.clientX) / 2, y: (a.clientY + b.clientY) / 2 }; }

  destroy(): void { for (const off of this.boundoff) off(); this.boundoff = []; this.idle(); } // AC-e4
}
